__NUXT_JSONP__("/fr/westwood", (function(a,b,c){return {data:[{details:{slug:a,pageTitle:"Campus de Westwood | Mentor Language Institute",pageDescription:b,title:"Campus de Westwood",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002Fkr-Ip37iVNE",subtitle:[b,"Westwood est célèbre pour être y acceuillier UCLA. Le campus de Westwood est situé à l'intersection du boulevard de Wilshire et de Westwood.","Nous sommes situés à seulement 1 minute de la ligne de bus principale sur Wilshire Blvd et Westwood Blvd. C'est un quartier très amusant et populaire pour les étudiants et les employés de bureau car il y a beaucoup de magasins, de restaurants et d'endroits sûrs à visiter."],landmark:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fsanta-monica.jpg",title:"A 20 minutes de Santa Monica par bus"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fbeverly-hills.jpg",title:"A 10 minutes de Beverly Hills par bus"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Flos-angeles-skyline.jpg",title:"A 60 minutes de Downtown LA par bus"}],gallery:{title:"Gallerie photo du campus de Westwood",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002F10880-building.jpg",title:"Nous sommes situés au premier étage de l'immeuble.",subtitle:"Vous n'aves pas besoin de prendre l'ascenseur pour aller en cours."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffront-desk.jpg",title:"La récéption"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fclassroom.jpg",title:"Les classes en murs de verre"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fcomputer-room.jpg",title:"La classe d'orninateurs"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fstudent-lounge.jpg",title:"Lounge d'étudiant"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffree-space.jpg",title:"Espace libre"}]},location:{title:"Location",map_link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3305.4289041796537!2d-118.44512238478478!3d34.05851788060419!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bb7e2b42fadf%3A0xad96227841e11efb!2s10880+Wilshire+Blvd%2C+Los+Angeles%2C+CA+90024!5e0!3m2!1sen!2sus!4v1513884279258"},video:[{title:"1. Comment se rendre à MLI Westwood Campus en Bus",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV2zydV7aWvA"},{title:"2. Comment se rendre au campus MLI Westwood en voiture",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F5FXkkyV3DZg"}],environment:{title:"Emplacement",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fucla.jpg",title:"À distance de marche de l'UCLA"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fhammer-museum.jpg",title:"Le musée Hammer, un des musées les plus célèbres de Los Angeles, est juste à côté de notre campus."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-library.jpg",title:"Il y a une bibliothèque derrière le campus où vous pouvez étudier."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fchevron-restaurant.jpg",title:"Il y a beaucoup de restaurants bon marché aux alentours."}]},accommodation:{title:"Hébergement",description:["Nous offrons des options de logement en famille d'acceuil ou en dortoir."],types:[{desc:["Dortoir \u003Cbr \u002F\u003EIl y a 40 chambres dans les dortoirs et vous pouvez vous rendre à l'école à pied ou en bus."],yt_link2:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV_eNdjw6Z1c"},{desc:["Famille d'acceuil"],other_desc:["Séjourner chez la famille d'acceuil est le meilleur moyen d'apprendre sur la culture américaine et d'augmenter vos chances d'améliorer votre anglais.","\u003Ca href=\"\u002Ffr\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  Plus de détails sur nos logements\u003C\u002Fa\u003E"]}]},courses:{title:"Nos Cours",lists:["ESL","TOEFL®","IELTS™","Conversation","TOEIC®"]},message:{title:c,image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-director.jpg",position:c,description:["\"Le campus de Westwood est situé près de UCLA. Il y a plusieurs endroits à visiter tels que des restaurants, des boutiques et des musées. Notre cours TOEFL est très populaire car de nombreux étudiants de Westwood poursuivent des études universitaires. De plus, nos prix des cours sont étonnamment raisonnables. Beaucoup de gens transfèrent à MLI pour cette raison! Vous pouvez télécharger la brochure pour plus d'information."]},dir:"\u002Fwestwood",path:"\u002Fwestwood\u002Ffr",extension:".json",createdAt:"2026-10-22T16:31:31.399Z",updatedAt:"2025-05-26T12:06:28.046Z"},lang:a}],fetch:{},mutations:void 0}}("fr","Westwood est un quartier vivant et unique situé à l'ouest de Los Angeles.","Message du directeur du campus")));